let hamburger=document.querySelector(".page-header__toggle-nav"),nav=document.querySelector(".page-header__nav");function hamburgerHide(){nav.classList.remove("page-header__nav--show"),hamburger.classList.remove("hamburger__click")}hamburger.addEventListener("click",function(e){e.preventDefault(),this.classList.contains("hamburger__click")?hamburgerHide():(nav.classList.add("page-header__nav--show"),hamburger.classList.add("hamburger__click")),nav.classList.contains("active")?(nav.classList.add("esc"),setTimeout(function(){nav.classList.remove("active"),nav.classList.remove("esc")},850)):nav.classList.add("active")});